extern crate rustc_span;extern crate rustc_data_structures;extern crate rustc_hashes;
use rustc_span::{Span,BytePos,DUMMY_SP};use rustc_span::hygiene::*;use rustc_span::edition::Edition;use rustc_span::symbol::{Symbol,sym};use rustc_span::def_id::{CRATE_DEF_ID,ModId};use rustc_span::source_map::{SourceMap,FilePathMapping};
use rustc_data_structures::stable_hash::{StableHashCtxt,StableHasher,RawSpan,RawDefId,StableHashControls};use rustc_data_structures::fingerprint::Fingerprint;use rustc_hashes::Hash64;use std::hash::Hasher;
struct Hcx;impl StableHashCtxt for Hcx{fn stable_hash_span(&mut self,s:RawSpan,h:&mut StableHasher){h.write_u64(s.0)}fn def_path_hash(&self,id:RawDefId)->Fingerprint{Fingerprint::new(Hash64::new(id.0 as u64+100),Hash64::new(id.1 as u64+1000))}fn stable_hash_controls(&self)->StableHashControls{StableHashControls{hash_spans:true}}fn assert_default_stable_hash_controls(&self,_:&str){}}
fn scope(value:Option<ExpnId>)->u32{value.map(|v|v.local_id.as_u32()).unwrap_or(u32::MAX)}
fn main(){let a:Vec<_>=std::env::args().skip(1).map(|s|s.parse::<usize>().unwrap()).collect();let(n,mode)=(a[0],a[1]);rustc_span::create_session_globals_then(Edition::Edition2015,&[],None,||{
 let sm=SourceMap::new(FilePathMapping::empty());let mut ids=vec![ExpnId::root()];let mut contexts=vec![SyntaxContext::root()];let mut current=SyntaxContext::root();
 for i in 0..n{
  let kind=match (i+mode)%5{0=>ExpnKind::Desugaring(DesugaringKind::FormatLiteral{source:mode%2==0}),1=>ExpnKind::Macro(MacroKind::Bang,sym::include),2=>ExpnKind::Macro(MacroKind::Attr,Symbol::intern("attr")),3=>ExpnKind::AstPass(AstPass::TestHarness),_=>ExpnKind::Desugaring(if i%2==0{DesugaringKind::ForLoop}else{DesugaringKind::QuestionMark})};
  let parent=if mode&2==0{ids[i]}else{ids[0]};let call=Span::new(BytePos(i as u32+10),BytePos(i as u32+11),if mode&1!=0{current}else{SyntaxContext::root()},None);
  let features=if i%2==0{Some(std::sync::Arc::from([Symbol::intern("feature")]))}else{None};
  let data=ExpnData::new(kind,parent,call,DUMMY_SP,features,Edition::Edition2024,Some(CRATE_DEF_ID.to_def_id()),Some(ModId::new_unchecked(CRATE_DEF_ID.to_def_id())),i%2==0,i%3==0,i%2==0,i%3==0);
  let id=LocalExpnId::fresh(data,Hcx).to_expn_id();ids.push(id);current=current.apply_mark(id,match(i+mode)%3{0=>Transparency::Transparent,1=>Transparency::SemiOpaque,_=>Transparency::Opaque});contexts.push(current);
 }
 for (i,&id)in ids.iter().enumerate(){let data=id.expn_data();let refs=data.allow_internal_unstable.as_ref().map(std::sync::Arc::strong_count).unwrap_or(0);println!("data {i} {} {} {refs}",data.is_root(),data.kind.descr());drop(data);let cause=id.expansion_cause();println!("cause {i} {} {}",cause.is_some(),cause.map(|s|s.lo().0).unwrap_or(0));for(j,&other)in ids.iter().enumerate(){println!("desc {i} {j} {}",id.is_descendant_of(other));}for(j,&c)in contexts.iter().enumerate(){println!("outerdesc {i} {j} {}",id.outer_expn_is_descendant_of(c));}}
 for(i,&c)in contexts.iter().enumerate(){let mut removed=c;let outer=removed.remove_mark();println!("remove {i} {} {}",removed.as_u32(),outer.local_id.as_u32());println!("external {i} {}",c.in_external_macro(&sm));for(j,&id)in ids.iter().enumerate(){let mut adjusted=c;let result=adjusted.adjust(id);println!("adjust {i} {j} {} {}",adjusted.as_u32(),scope(result));let mut normalized=c;let result=normalized.normalize_to_macros_2_0_and_adjust(id);println!("normaladjust {i} {j} {} {}",normalized.as_u32(),scope(result));for(k,&glob)in contexts.iter().enumerate(){let span=DUMMY_SP.with_ctxt(glob);let mut value=c;let result=value.glob_adjust(id,span);println!("glob {i} {j} {k} {} {} {}",value.as_u32(),result.is_some(),scope(result.flatten()));let mut value=c;let result=value.reverse_glob_adjust(id,span);println!("reverse {i} {j} {k} {} {} {}",value.as_u32(),result.is_some(),scope(result.flatten()));println!("eq {i} {j} {k} {}",c.hygienic_eq(glob,id));}}
  let span=Span::new(BytePos(99),BytePos(100),c,None);for(j,&to)in contexts.iter().enumerate(){let walked=walk_chain(span,to);let collapsed=walk_chain_collapsed(span,DUMMY_SP.with_ctxt(to));println!("walk {i} {j} {} {} {} {}",walked.lo().0,walked.ctxt().as_u32(),collapsed.lo().0,collapsed.ctxt().as_u32());}
 }
 println!("--final--\n{}",debug_hygiene_data(false));
});}
